/*
 * Builds the single-file version of the game: the stylesheet and every script
 * inlined into one HTML file, so it runs from a double-click (file://) or any
 * static host with nothing to install.
 *   node tools/bundle.js                    -> dist/simsoc6.html
 *   node tools/bundle.js out.html           -> custom path
 *   node tools/bundle.js out.html --fragment
 *       -> body-only fragment (title + style + markup + scripts, no document
 *          skeleton) for hosts that wrap the page in their own <html>/<head>.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const read = f => fs.readFileSync(path.join(ROOT, f), 'utf8');

function build(opts) {
  opts = opts || {};
  const pkg = JSON.parse(read('package.json'));
  let html = read('index.html');
  const css = read('css/style.css');
  html = html.replace(/<link rel="stylesheet" href="css\/style\.css">/, () => '<style>\n' + css + '\n</style>');
  html = html.replace(/<script src="(js\/[\w-]+\.js)"><\/script>/g, (m, src) => {
    const js = read(src);
    if (/<\/script/i.test(js)) throw new Error(src + ' contains "</script>", which cannot be inlined');
    return '<script>\n' + js + '\n</script>';
  });
  if (/<(link rel="stylesheet"|script src=)/.test(html)) throw new Error('an external file was left in index.html');
  const stamp = '<!-- SIMSOC 6 Manager v' + pkg.version + ' - single-file build, generated by tools/bundle.js -->';
  if (!opts.fragment) return html.replace('<!DOCTYPE html>', '<!DOCTYPE html>\n' + stamp);
  const title = /<title>([^<]*)<\/title>/.exec(html)[1];
  const style = /<style>[\s\S]*?<\/style>/.exec(html)[0];
  const body = /<body>([\s\S]*)<\/body>/.exec(html)[1].trim();
  return stamp + '\n<title>' + title + '</title>\n' + style + '\n' + body + '\n';
}

if (require.main === module) {
  const args = process.argv.slice(2);
  const fragment = args.indexOf('--fragment') >= 0;
  const out = args.filter(a => a[0] !== '-')[0] || path.join('dist', 'simsoc6.html');
  const file = path.isAbsolute(out) ? out : path.join(ROOT, out);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const html = build({ fragment: fragment });
  fs.writeFileSync(file, html);
  console.log('Wrote ' + path.relative(process.cwd(), file) + ' (' + (html.length / 1024).toFixed(0) + ' KB' + (fragment ? ', fragment' : '') + ')');
}

module.exports = { build };
